#include <bits/stdc++.h>
using namespace std;

using u64 = uint64_t;
using u128 = __uint128_t;

u64 modMul(u64 a, u64 b, u64 mod) {
    return static_cast<u64>((u128)a * b % mod);
}

u64 modPow(u64 a, u64 e, u64 mod) {
    u64 result = 1;
    while (e) {
        if (e & 1) result = modMul(result, a, mod);
        a = modMul(a, a, mod);
        e >>= 1;
    }
    return result;
}

bool isPrime(u64 n) {
    if (n < 2) return false;
    for (u64 p : {2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL, 19ULL,
                  23ULL, 29ULL, 31ULL, 37ULL}) {
        if (n % p == 0) return n == p;
    }

    u64 d = n - 1, s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (u64 a : {2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL,
                  9780504ULL, 1795265022ULL}) {
        if (a % n == 0) continue;

        u64 x = modPow(a % n, d, n);
        if (x == 1 || x == n - 1) continue;

        bool composite = true;
        for (u64 r = 1; r < s; ++r) {
            x = modMul(x, x, n);
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite) return false;
    }
    return true;
}

u64 pollardRho(u64 n) {
    if (n % 2 == 0) return 2;
    if (n % 3 == 0) return 3;

    static mt19937_64 rng(
        chrono::steady_clock::now().time_since_epoch().count()
    );

    while (true) {
        u64 c = uniform_int_distribution<u64>(1, n - 1)(rng);
        u64 x = uniform_int_distribution<u64>(0, n - 1)(rng);
        u64 y = x;
        u64 divisor = 1;

        auto f = [&](u64 value) {
            return (modMul(value, value, n) + c) % n;
        };

        while (divisor == 1) {
            x = f(x);
            y = f(f(y));
            u64 difference = x > y ? x - y : y - x;
            divisor = gcd(difference, n);
        }

        if (divisor != n) return divisor;
    }
}

void factorize(u64 n, map<u64, int>& factors) {
    if (n == 1) return;
    if (isPrime(n)) {
        ++factors[n];
        return;
    }

    u64 divisor = pollardRho(n);
    factorize(divisor, factors);
    factorize(n / divisor, factors);
}

void printU128(u128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }

    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    u64 n, k, m, d;
    cin >> n >> k >> m >> d;

    if (m == 1) {
        cout << 1 << '\n';
        return 0;
    }

    map<u64, int> factorMap;
    factorize(n, factorMap);

    vector<pair<u64, int>> factors(factorMap.begin(), factorMap.end());
    u128 answer = m;

    function<void(size_t, u64)> generateDivisors =
        [&](size_t index, u64 divisor) {
            if (index == factors.size()) {
                if (divisor < 2) return;

                u128 denominator = (u128)divisor * k;
                u128 groups = ((u128)n + denominator - 1) / denominator;

                if (groups <= d) {
                    answer = max(answer, groups * divisor);
                }
                return;
            }

            const auto [prime, exponent] = factors[index];
            u64 value = divisor;

            for (int e = 0; e <= exponent; ++e) {
                generateDivisors(index + 1, value);
                if (e == exponent || value > m / prime) break;
                value *= prime;
            }
        };

    generateDivisors(0, 1);

    printU128(answer);
    cout << '\n';
    return 0;
}

